using System;
using System.Threading;
using System.Threading.Channels;
using System.Threading.Tasks;

public class Program
{
    public static async Task Main()
    {
        // Bounded Channel kapasitas 3
        var options = new BoundedChannelOptions(3)
        {
            FullMode = BoundedChannelFullMode.Wait,
            SingleReader = true,
            SingleWriter = true
        };
        var channel = Channel.CreateBounded<int>(options);

        // Consumer Worker yang membaca data
        var consumerTask = Task.Run(async () =>
        {
            Console.WriteLine("[Consumer] Siap memproses data...");
            await foreach (var item in channel.Reader.ReadAllAsync())
            {
                Console.WriteLine($"[Consumer] Memproses item: {item}");
                await Task.Delay(20);
            }
        });

        // Producer: Menghasilkan 5 item
        for (int i = 1; i <= 5; i++)
        {
            Console.WriteLine($"[Producer] Menulis item {i}...");
            await channel.Writer.WriteAsync(i);
        }

        channel.Writer.Complete();
        await consumerTask;
        Console.WriteLine("[Sistem] Seluruh pemrosesan channel selesai.");
    }
}

